#: The bills and coins on the paper form (the keys of `denomination_breakdown`).
DENOMINATIONS = (1000, 500, 200, 100, 50, 20, 10, 5, 1)


def _breakdown_total(counts):
    """Sum of denomination x count for a stored breakdown ({"1000": 2, ...}); Decimal.

    Refuses (ValueError) a shape it does not recognise rather than guessing: a frozen money total
    must never be invented by a migration.
    """
    if not counts:
        return Decimal("0.00")
    if not isinstance(counts, dict):
        raise ValueError("denomination_breakdown is not an object")
    total = Decimal("0")
    for key, value in counts.items():
        if int(key) not in DENOMINATIONS or isinstance(value, bool) or int(value) != value or value < 0:
            raise ValueError(f"unexpected denomination entry {key!r}: {value!r}")
        total += Decimal(int(key)) * int(value)
    return total.quantize(Decimal("0.01"))


